CREATE TABLE town(
    id          INTEGER PRIMARY KEY,
    name        TEXT NOT NULL,
    admin1      TEXT,
    countryCode TEXT REFERENCES country(code),
    latitude    REAL,
    longitude   REAL,
    population  INTEGER
);
CREATE TABLE user(
    id              INTEGER PRIMARY KEY,
    username        TEXT,
    poopsCount      INTEGER,
    pinColor        TEXT,
    createdAt       DATETIME,
    badgesCount     INTEGER,
    followersCount  INTEGER,
    followingsCount INTEGER,
    countryCount    INTEGER,
    isPro           BOOLEAN,
    isPrivate       BOOLEAN,
    poopsPerDay     REAL
);
CREATE INDEX idx_poop_user ON poop(userId);
CREATE INDEX idx_poop_town ON poop(townId);
CREATE INDEX idx_town_country ON town(countryCode);
COMMIT;
