INSERT INTO "poop" VALUES(252236434,'2026-10-26T15:34:01.211Z',48.31537808770981,14.285680912435049,0,'Hatte vorhin schon eine Scheißerei, dachte mir, gut, das solls gewesen sein. Aber natürlicherweise werde ich nicht von der Bomb verschont. Die gleißend-brennende anale Masse, die sich meinem Darmtrakt hier entzog, ist schlicht und ergreifend nicht zu vergleichen. Schon lange hatte ich keinen derartig brutalen Schiss mehr, schon lange sehnte sich mein Rektum nicht mehr nach einem jähen Ende. Doch das hier war anders. The Bomb brutalisiert meine Innereien auf eine dermaßen gewaltsame Weise, dass mir die Worte fehlen. Das Einzige, was mir hier bleibt, ist schlichte, bescheidene Resignation. Du hast gewonnen, Bomb. Ich verneige mich vor dir und deiner Würze. Mögest du meine Milz und mich über den Styx hieven und uns dort in den Schlund schleudern.',NULL,'Elfenbeinturm',0,NULL,5358536,2772400);
