INSERT INTO "poop" VALUES(252619917,'2026-10-31T06:34:06.639Z',44.864589032919689,0.79849295318126679,0,'another big circle poop. One solid piece probably 20 inches long. Post espresso poop. The espresso maker that thought was $5000 was actually $700. I kind of want one, but it’s kind of expensive for an expresso/coffee machine. I like my DeLonghi Alicia machine just fine and it cost $35. Although with this machine, I could taste that he gets all of the coffee extract out of the coffee. Because I get pretty wired off of it. One cool thing that happened which my mom would’ve really loved is her casket was on this Roomba type of mechanical machine that moved my mom from the funeral to the Crematorium. I took a video, but it won’t let me show it on here probably too long.','#0025ff','pigeonnier toilet missed login',5,'clear_the_room',3278828,3008469);
