INSERT INTO "poop" VALUES(252623501,'2026-10-31T08:23:27.869Z',52.429804086448478,13.215290755033489,0,'Leider habe ich etwas zeitstress und kann deswegen noch keine volle Respondenz für Alex schreiben. Also werde ich die Punkte in mehreren Schissen abarbeiten. Erstmal muss ich allerdings übergreifend sagen, dass innerhalb des Textes auch eine schwankende interne Logik zu erkennen ist, und der Text ganz nach dem liberalen Banalitäten Genre des "wird sind ein tief gespaltetes Land" funktioniert. Alex bezieht sich viel mehr auf irgendwelche erdachten Grundpfeiler sowie Ad Hominem gegen mich und Jona, und vergisst dabei die eigentliche Thematik. Und wer davon überzeugt ist, weil er sich innerhalb des Textes überwiegend unnötig wiederholt, der läuft auch der Karotte nach die an einer Angel hängt. Mehr werde ich allerdings in der voraussichtlich bald kommenden zweiten Sitzung schreiben.',NULL,'Zuhause Ossi',3,NULL,6938902,2888523);
