INSERT INTO "poop" VALUES(252624858,'2026-10-31T08:45:54.354Z',46.532885265634903,6.4921682327985764,0,'lui je le travaille depuis ce matin 7h, j''ai attendu le moment propice, le moment ultime, le meilleur moment pour le lâcher, et ça n''a pas déçu il est descendu tel une goutte de pluie tombant sur le sol. C''est ce genre d''expérience qui donne de la confiance en soi car en parfaite communion entre le ressenti et le réel. Il est tellement agréable que ça m''ouvre l''esprit à toute formes d''idée/ imagination, ça pousse à aller plus loin. En somme, le dernier moment encore tranquille de la matinée qui mets bien en confiance pour le reste de la journée voir carrément du weekend.',NULL,'travail',5,'low_key',6610871,2659587);
