INSERT INTO "poop" VALUES(252703364,'2026-11-01T07:58:58.207Z',0.0,0.0,0,'Od cca desiatej vecer som na shitteri bola uz asi 3-4 krat. Toto je jedine hovno na ktore mam energiu urobit review z celkovo jasnych dovodov uvedenych v titule tohto hovna. Domov som prisla absolutne rozjebana, ked som sa snazila potichu zamknut dvere po tom co sme s kamaratom este vypratali jeho auto a pozostatky vecera boli velmi hlasne vyhodene do kosa a asi sa tam aj rozbili, ups, mi kluce z ruky vypadli a musela som ich dvyhat a potom som nevedela strcit kluc do dveri q spadli zas. skoro som to vzdala alle do tretice vsetko dobre a devre boli zamknute. dalsia uloha bolo si vyzut topanky alle z urcitych dovodov (zozrala som kebab) som sa nevedela predhnut inak by tie urcite dovody (ten kebab) skoncili na rohoske a baba by ma asi vyhodila z domu. takze topanky so mnou isli do izby. bohuzial toto bolo obdobie kedy ten alkohol zacal hitovat najviac a vela si nepamatam alle jedna vec ktoru si pamatam je ze som sa sla schovat pred rodicmi do sprchy co nefungovalo lebo moj otec prisiel dat isnoekciu az jed som si poprvy krat sadla na shitter a musela som predstierat ze je vsetko ok a nevidim dvere 2 krat. asi sa mi to podarilo lebo isiel nazad z kade prisiel no v tom momente som este nevedela ze najvacsi problem len pride. vytriet si kakac. z plneho srdca budem dufat ze som sa s toaletakom trafila kazdy wipe a ze som si ruky umyla poriadne. of course nemoze chybat inspekcia od mamky ktora sa vdaka bohu stala ked som sa dajak, uz bez topanok, dotrepala do postele. mamka za mnou prisla s tym ze vecera je hotova a ze si ju mam dochutit bo ju vibec nedochutovala co momentalne pocitujem lebo ju zerem vonku na terase na cerstvom vzduchu s poharikom srudenej cistej vody priamo z vodovodu. pravdaze z postele som sa postavit nevedela a musela som to zahrat ze je zas vsetko ruzove a pekne aj ked to nebolo. aj po tom kebabe som bola extremne hladna alle riskovat to ze mam vyst do kuchyne po schodoch a odprezentovat sa druzine (mojim pravdepodobne suspicious rodicom) som radsej nesla. dalej si uz velmi fakt nepamatam co sa dialo alle viem ze som sa rano zobudila asi o piatej na to ze sa o 5 sekund postim a musela som behat na zachod kde som dropla dalsie kulo vecera (uz skorej rana alle to by az tak dobre neznelo). toto kulo bolo uz viac peacefull a potom som vypila celu 2 litrovu flasku vody a skoro som sa doryhala alle podla mna worth it - hydracia je key! po navrateni do postele som si uvedomilaze mam oholene nohy. jak. a k tomu este aj celkovo dobre. na shitter som potom asi okolo siedmej isla este raz z tym ze som asi zobudila cely dom bo som pekne povedane dzigla do dveri s celou mojou vahou (cca 100 kil typujem) a dvere pravdaze ozmili nase rychle zblizenie dverovym vykrikom (jebli). eventfull part tohto kaku bolo to ze som si na tom zachode trosku zdriemla. dalsi kak bol uz tento o ktorom som v tomto prispevku mala infromovat a bohuzial naneho nemam dobre pocity. bol tekuty a stipe ma ric. alle inak sa citim celkov dobre papam moju nedochutenu veceru na terase a kukam mojeho fav streamera (kota ibushi san)❤️❤️❤️dufam ze to neolo prilis dlhe na precitanie ked si to vobec dakto precital…',NULL,'po opici',5,NULL,7343680,NULL);
