INSERT INTO "poop" VALUES(252704976,'2026-11-01T02:03:00.000Z',27.71486809742412,-97.400963343679891,0,'3 day worth of local denver cuisine was knocking at the door when we made it home. i had a moment to say hello to the cats before i had to pay a visit to my own throne. and boy was it a visit. flaming log of doom after flaming log of doom. it was soft and right when i thought it was done here comes another one. it was so bad and i had to use the bidet to rinse my booty. peppermint was very curious about the sound of the bidet she kept sniffing where my cheeks hit the seat. no peaceful dumping allowed according to her. after i wash my booty a couple more wipes and i was out of there. and sure enough, one flush was not enough. i thought it went down but found out later there was still a floater and some change along with a big huge wide skid mark. so had to flush twice. no clogging so it was probably just too much to go down in one flush. had to use the poo pourri spray to keep the smell down. that stuff very effective. not great experience but it could have been worse all things considered',NULL,'Home',2,'noticeable',924952,4683416);
