INSERT INTO "poop" VALUES(252726977,'2026-11-01T14:47:55.163Z',40.74880103477588,-73.993746377527714,0,'Jetait en train de manger mes skittles récoltes par mes esclaves hier lors du treaj or treating quand je sentis souris une envie de libérer la crotte arrivé. Je me diriges alors vers les toilettes sur les quelles la porte n’avait pas été décorée de caca de vasco et m’installa gentillement sur le trône. Je laissas alors paisiblement sortir mon étron d’Halloween. Quand je me relevas pour découvrir l’œuvre concoctée par mon intestin et mon anus, j’aperçus quelques chose de plus terrifiant que tous se que j’avais entendu y voir au long de cette semaine horrifique d’Halloween American. Il s’agissait d’une crotte de 25 cm de long, reflet proportionnelle à la longueur des buildings new-yorkais',NULL,'New York',4,'noticeable',7230067,5106184);
